CREATE VIEW "TEST_AP"."IBT1" ( "ItemCode", "BatchNum", "WhsCode", "LineNum", "ItemName", "BaseType", "BaseEntry", "BaseNum", "BaseLinNum", "DocDate", "Quantity", "CardCode", "CardName", "Direction", "CreateDate", "BsDocType", "BsDocEntry", "BsDocLine", "DataSource", "UserSign" ) AS SELECT  "ItemCode"  ,"BatchNum"  ,"WhsCode"  ,(			select count(1) from "TEST_AP".IBT1_LINK b 		where b."ItemCode" = a."ItemCode" and b."BatchNum" = a."BatchNum" and b."WhsCode" = a."WhsCode" and b."LogEntry" < a."LogEntry"  ) as "LineNum"  ,"ItemName"  ,"BaseType" ,"BaseEntry" ,"BaseNum"  ,"BaseLinNum"  ,"DocDate"  ,"Quantity" ,"CardCode"  ,"CardName"  ,"Direction"  ,"CreateDate"  ,"BsDocType"  ,"BsDocEntry"  ,"BsDocLine"  ,"DataSource"  ,"UserSign" from "TEST_AP".IBT1_LINK a WITH READ ONLY